window.Settings=(()=>{
 let draft=null;
 const regions=Object.keys(V.limits),count=(r)=>draft.selected.filter(id=>V.get(id).region===r).length;
 const equalSets=(a,b)=>a.length===b.length&&a.every(x=>b.includes(x));
 function discard(){draft=null}
 function ensure(){const basis=V.ids(state);if(!draft||!equalSets(draft.basis,basis))draft={basis:[...basis],quotas:V.quotas(basis),selected:[...basis],step:1};}
 function validQuotas(){return regions.every(r=>Number.isInteger(draft.quotas[r])&&draft.quotas[r]>=V.limits[r].min&&draft.quotas[r]<=V.limits[r].max)&&regions.reduce((n,r)=>n+draft.quotas[r],0)===32}
 function selectedValid(){return validQuotas()&&regions.every(r=>count(r)===draft.quotas[r])&&V.validRoster(draft.selected)}
 function render(){ensure();const c=$('content');if(draft.step===1)renderQuotas(c);if(draft.step===2)renderChoices(c);if(draft.step===3)renderReview(c)}
 function steps(){return `<div class="setup-steps">${['Phân bổ suất','Chọn đội','Xác nhận'].map((n,i)=>`<span class="${draft.step===i+1?'current':''}"><b>${i+1}</b>${n}</span>`).join('')}</div>`}
 function setQuota(r,value){ensure();if(!regions.includes(r))return;draft.quotas[r]=Number(value);render()}
 function adjust(r,delta){const n=draft.quotas[r]+delta;if(n>=V.limits[r].min&&n<=V.limits[r].max)setQuota(r,n)}
 function defaults(){draft.quotas=V.quotas(V.defaultIds);render()}
 function next(){if(!validQuotas()){toast('Cần đủ 32 suất và đúng giới hạn từng khu vực.');return}draft.step=2;render()}
 function back(){draft.step=Math.max(1,draft.step-1);render()}
 function progressText(){let total=regions.reduce((n,r)=>n+draft.quotas[r],0);if(!Number.isFinite(total))return 'Vui lòng nhập số suất hợp lệ.';return total===32?'Đã phân bổ đủ 32 suất.':total<32?`Còn thiếu ${32-total} suất. Hãy tăng số suất ở khu vực khác.`:`Dư ${total-32} suất. Hãy giảm số suất ở khu vực khác.`}
 function renderQuotas(c){let current=V.quotas(draft.basis),total=regions.reduce((n,r)=>n+draft.quotas[r],0);c.innerHTML=`<div class="section-head"><div><h2>Tùy chỉnh giải đấu</h2><p class="sub">Bạn quyết định cơ hội của từng khu vực. Thể thức 32 đội được giữ nguyên.</p></div><button onclick="Settings.defaults()">Phân bổ mặc định</button></div>${steps()}<div class="quota-layout"><div class="quota-cards">${regions.map(r=>`<article class="panel quota-card"><div><span class="badge">${r}</span><h3>${names[r]}</h3><p class="sub">Hiện tại ${current[r]} đội · Giới hạn ${V.limits[r].min}–${V.limits[r].max} đội</p></div><div class="stepper"><button aria-label="Giảm suất ${names[r]}" ${draft.quotas[r]<=V.limits[r].min?'disabled':''} onclick="Settings.adjust('${r}',-1)">−</button><input aria-label="Số suất ${names[r]}" type="number" min="${V.limits[r].min}" max="${V.limits[r].max}" step="1" value="${Number.isFinite(draft.quotas[r])?draft.quotas[r]:''}" onchange="Settings.setQuota('${r}',this.value)"><button aria-label="Tăng suất ${names[r]}" ${draft.quotas[r]>=V.limits[r].max?'disabled':''} onclick="Settings.adjust('${r}',1)">+</button></div></article>`).join('')}</div><aside class="panel quota-summary"><div class="eyebrow">TỔNG SỐ SUẤT</div><div class="quota-total ${validQuotas()?'valid':''}">${Number.isFinite(total)?total:'–'}<small>/32</small></div><p class="sub" role="status">${progressText()}</p><div class="allocation-bar">${regions.map((r,i)=>`<i class="region-${r}" style="flex:${Math.max(0,draft.quotas[r]||0)}" title="${names[r]}: ${draft.quotas[r]}"></i>`).join('')}</div>${regions.map(r=>`<div class="allocation-line"><span><i class="region-${r}"></i>${r}</span><b>${draft.quotas[r]} đội</b></div>`).join('')}<button class="primary" ${validQuotas()?'':'disabled'} onclick="Settings.next()">Tiếp tục: chọn đội →</button><p class="sub" style="margin-top:12px">Thay đổi tại đây chưa ảnh hưởng giải đang chơi.</p></aside></div>`;}
 function toggle(id,checked){ensure();const t=V.get(id);if(!t)return;if(checked){if(count(t.region)>=draft.quotas[t.region]||draft.selected.includes(id))return;draft.selected.push(id)}else draft.selected=draft.selected.filter(x=>x!==id);render()}
 function top(r){draft.selected=[...draft.selected.filter(id=>V.get(id).region!==r),...V.regionTeams(r).slice(0,draft.quotas[r]).map(t=>t.id)];render()}
 function needed(r){let n=count(r)-draft.quotas[r];return n>0?`Cần bỏ ${n} đội`:n<0?`Cần thêm ${-n} đội`:'Đã chọn đủ'}
 function option(t){const selected=draft.selected.includes(t.id),full=count(t.region)>=draft.quotas[t.region];return `<label class="roster-option ${selected?'selected':''}"><input type="checkbox" ${selected?'checked':''} ${!selected&&full?'disabled':''} onchange="Settings.toggle('${t.id}',this.checked)"><span class="flag">${t.flag}</span><span class="roster-name">${t.name}<small>#${V.regionTeams(t.region).findIndex(x=>x.id===t.id)+1} khu vực · #${t.rank} thế giới</small></span>${selected?'<span class="selection-tick">✓</span>':''}</label>`}
 function renderChoices(c){const missing=regions.filter(r=>count(r)!==draft.quotas[r]);c.innerHTML=`<div class="section-head"><div><h2>Chọn đội cho từng khu vực</h2><p class="sub">Đội hiện tại được giữ sẵn. Tự bỏ hoặc thêm đội để khớp số suất bạn đã đặt.</p></div><span class="round-tag">${draft.selected.length}/32 ĐỘI ĐÃ CHỌN</span></div>${steps()}<div class="selection-note ${missing.length?'needs-action':'complete'}" role="status">${missing.length?missing.map(r=>`${r}: ${needed(r).toLowerCase()}`).join(' · '):'Tất cả khu vực đã đủ đội. Bạn có thể xem lại trước khi áp dụng.'}</div>${regions.map(r=>{const old=V.regionTeams(r).filter(t=>draft.basis.includes(t.id)),reserves=V.regionTeams(r).filter(t=>!draft.basis.includes(t.id));return `<details class="panel roster-region" ${count(r)!==draft.quotas[r]?'open':''}><summary><span><span class="badge">${r}</span> <b>${names[r]}</b></span><span class="${count(r)===draft.quotas[r]?'roster-ready':'roster-needed'}">${count(r)}/${draft.quotas[r]} · ${needed(r)}</span></summary><div class="roster-body"><div class="section-head"><p class="sub">Xếp theo BXH khu vực · bỏ một đội trước nếu muốn đổi sang đội dự phòng.</p><button onclick="Settings.top('${r}')">Chọn top ${draft.quotas[r]} theo BXH</button></div><div class="roster-columns"><section><h3>Đội đang dự giải <span class="badge">${old.length}</span></h3><div class="roster-list">${old.map(option).join('')}</div></section><section><h3>Đội dự phòng <span class="badge">${reserves.length}</span></h3><div class="roster-list">${reserves.map(option).join('')}</div></section></div></div></details>`}).join('')}<div class="setup-footer"><button onclick="Settings.back()">← Phân bổ suất</button><span class="sub">${selectedValid()?'Đã chọn đủ 32 đội':'Chưa thể xác nhận: cần chọn đúng số đội của từng khu vực'}</span><button class="primary" ${selectedValid()?'':'disabled'} onclick="Settings.review()">Xem lại & xác nhận →</button></div>`;}
 function review(){if(!selectedValid()){toast('Chọn đủ đội cho từng khu vực trước khi xác nhận.');return}draft.step=3;render()}
 function renderReview(c){const added=draft.selected.filter(id=>!draft.basis.includes(id)),removed=draft.basis.filter(id=>!draft.selected.includes(id)),played=state.rounds.flat().filter(m=>m.sets).length;c.innerHTML=`<div class="section-head"><div><h2>Sẵn sàng cho một giải đấu mới?</h2><p class="sub">Kiểm tra danh sách trước khi áp dụng.</p></div><span class="round-tag">32 ĐỘI · 31 VÒNG · 496 TRẬN</span></div>${steps()}<div class="notice"><b>${added.length} đội được thêm · ${removed.length} đội được bỏ</b><p>Lịch league và nhánh playoff sẽ được tạo lại theo danh sách mới.${played?` Giải hiện tại có ${played} trận league đã đấu; các kết quả đó không chuyển sang giải mới.`:''} Một bản sao tiến độ hiện tại sẽ được giữ trên thiết bị.</p><button onclick="exportSave()">Xuất tiến độ hiện tại trước khi đổi</button></div><div class="change-grid"><div class="panel change-card"><h3>+ Thêm vào giải</h3>${added.length?added.map(id=>`<div>${team(id)}</div>`).join(''):'<p class="sub">Không thêm đội mới.</p>'}</div><div class="panel change-card"><h3>− Chuyển sang dự phòng</h3>${removed.length?removed.map(id=>`<div>${team(id)}</div>`).join(''):'<p class="sub">Không bỏ đội nào.</p>'}</div></div><div class="region-grid">${regions.map(r=>`<div class="panel region-card"><span class="badge">${r} · ${draft.quotas[r]} ĐỘI</span><h3 style="margin-top:12px">${names[r]}</h3>${V.regionTeams(r).filter(t=>draft.selected.includes(t.id)).map(t=>`<div class="team"><span class="flag">${t.flag}</span>${t.name}${added.includes(t.id)?'<small>+ Mới</small>':''}</div>`).join('')}</div>`).join('')}</div><div class="setup-footer"><button onclick="Settings.back()">← Chọn đội</button><button class="primary" onclick="Settings.apply()">Xác nhận & tạo giải mới →</button></div>`;}
 function apply(){if(!draft||draft.step!==3||!selectedValid())return;if(!equalSets(draft.basis,V.ids(state))){discard();render();toast('Danh sách giải đã thay đổi. Hãy tùy chỉnh lại.');return}if(state.rounds.flat().some(m=>m.sets)&&!confirm('Tạo giải mới với 32 đội đã chọn? Lịch đấu và kết quả hiện tại sẽ được thay thế. Bạn có thể xuất tiến độ trước khi tiếp tục.'))return;const selected=V.catalog.filter(t=>draft.selected.includes(t.id)).map(t=>t.id);window.Cloud?.backupCurrent();state=V.fresh(selected);discard();round=0;tab='league';save();window.render();toast('Đã tạo giải mới với danh sách bạn chọn!')}
 return{render,discard,setQuota,adjust,defaults,next,back,toggle,top,review,apply};
})();
